Stop.command:
PATH="$HOME/.local/bin:$PATH"; command -v factory-core >/dev/null 2>&1 || { payload=$(cat); if printf '%s' "$payload" | grep -q '"continuationActive"[[:space:]]*:[[:space:]]*true' || printf '%s' "$payload" | grep -q '"fullyIdle"[[:space:]]*:[[:space:]]*false' || printf '%s' "$payload" | grep -Eiq '"terminationReason"[[:space:]]*:[[:space:]]*"(USER_CANCELED|ERROR|MAX_)'; then printf '{"decision":"stop"}
'; else msg='BLOCKED: factory-core is not installed. Run ./install.sh --core-only from the agentic-software-factory repository, then factory-core doctor.'; printf '%s
' "$msg" >&2; printf '{"decision":"continue","reason":"%s"}
' "$msg"; fi; exit 0; }; factory-core holdout-gate --platform antigravity
